import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newMinSum) public {
        // Keep MinSum admissible: non-zero is fine; attacker sends enough Ether to meet balance requirements
        vm.assume(newMinSum > 0);
        address alice = address(0x1000);
        vm.deal(alice, 10 ether);

        // Initialize the contract so SetMinSum/SetLogFile etc. are available
        c.Initialized();
        c.SetMinSum(newMinSum);
        c.SetLogFile(address(0x2000));

        // Alice deposits enough to satisfy balance >= MinSum later
        vm.prank(alice);
        c.Put{value: 1 ether}(0);
        vm.warp(block.timestamp + 1);

        // Record MinSum before the call that triggers the difference
        uint256 minSumBefore = c.MinSum();

        // Try to collect; a reentrant caller could call SetMinSum(newMinSum+1) inside Collect
        vm.prank(alice);
        try c.Collect(1 ether) { } catch { }

        // The universal invariant: MinSum must never increase as a result of Collect
        assertTrue(c.MinSum() <= minSumBefore);
    }
}

