contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMin, uint256 lockTime, uint256 collectAmt) public {
        // 1. admissible domain: MinSum must be reasonable, and amounts must avoid overflow
        vm.assume(initialMin > 0);
        vm.assume(initialMin < type(uint256).max / 2);
        vm.assume(lockTime < type(uint256).max - block.timestamp);
        vm.assume(collectAmt > 0 && collectAmt <= initialMin);

        // 2. setup: initialize contract and set MinSum
        c.Initialized();
        c.SetMinSum(initialMin);

        // Fund this contract and put into C so we have balance and unlock time
        address actor = address(this);
        uint256 deposit = initialMin + 1; // ensure balance >= MinSum
        vm.deal(actor, deposit);
        c.Put{value: deposit}(lockTime);

        // Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minBefore = c.MinSum();

        // 3. Drive Collect
        c.Collect(collectAmt);

        // Assert: MinSum must be unchanged after Collect (reentrancy in bug version could alter it via SetMinSum)
        assertEq(c.MinSum(), minBefore, "MinSum changed after Collect");
    }
