pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(0x1234));
        c.Initialized();
    }
    function testFuzz_property(uint256 _am, uint256 deposit, uint256 lockTime, uint8 reentrantVal) public {
        // Bound _am and deposit to avoid overflow in Put and ensure balance >= _am
        _am = bound(_am, 1, type(uint128).max);
        deposit = bound(deposit, _am, type(uint128).max);
        // Ensure lockTime doesn't overflow when added to block.timestamp
        lockTime = bound(lockTime, 0, type(uint256).max - block.timestamp);
        // Ensure MinSum is set to a value <= deposit to pass the Collect check
        vm.assume(reentrantVal <= deposit);

        // Setup: fund actor and Put
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(lockTime);
        // Warp past unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attempt a Collect that could trigger reentrancy if flawed
        // In buggy version, Collect may call back to SetMinSum via attacker, increasing MinSum
        // We simulate this by having the Collect call itself trigger SetMinSum (reentrant)
        // But we cannot control the reentrant call directly; the fuzzer will explore state.
        // To expose the bug, we need the Collect to revert in original but succeed in mutant?
        // Actually, the property is: if Collect succeeds, MinSum must not be larger than before.
        bool success;
        try c.Collect(_am) {
            success = true;
        } catch {
            success = false;
        }
        if (success) {
            uint256 minSumAfter = c.MinSum();
            // General rule: MinSum must not increase due to a successful Collect
            assertTrue(minSumAfter <= minSumBefore);
        }
    }
}

