pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 _am, uint8 _minSum, uint8 logAddr) public {
        // 1. Admissible domain: MinSum > 0 and _am > 0 and depositAmount >= _am.
        vm.assume(_am > 0 && _minSum > 0);
        vm.assume(depositAmount >= _am);
        // 2. Setup: Initialize and set MinSum, deploy a LogFile to unblock Initialized, fund and deposit.
        address log = address(uint160(logAddr) + 1); // ensure non-zero address
        vm.assume(log.code.length == 0);
        c.SetMinSum(_minSum);
        c.SetLogFile(log);
        c.Initialized();
        address actor = address(0x1000);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(0);
        // Warp past unlock time so Collect is allowed.
        vm.warp(block.timestamp + 1);
        // 3. Capture MinSum before Collect.
        uint256 minSumBefore = c.MinSum();
        // 4. Execute Collect as the actor.
        vm.prank(actor);
        c.Collect(_am);
        // 5. Assert: After a successful Collect (which happens because conditions hold),
        // if MinSum was non-zero before, it must still be non-zero and strictly less than the actor's remaining balance.
        // The buggy modifier allows reentrant SetMinSum to arbitrarily change MinSum or balance,
        // breaking this invariant.
        uint256 balAfter = c.Acc(actor).balance;
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumBefore > 0 ? (minSumAfter > 0 && minSumAfter < balAfter) : true);
    }
}

