contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callCount) public {
        // callCount = number of times we attempt to call Initialized
        // Ensure we try at least twice to trigger the reentrancy bug
        callCount = bound(callCount, 2, 10);
        // Track how many times Initialized actually succeeded (did not revert)
        uint256 successCount = 0;
        for (uint256 i = 0; i < callCount; i++) {
            try c.Initialized() {
                successCount++;
            } catch {
            }
        }
        // At this point, if any call succeeded, the correct contract
        // should have set intitalized = true. The buggy version
        // prevents the state change, so it remains false.
        bool isInitialized = c.intitalized();
        // General rule: if at least one call succeeded, intitalized must be true.
        assertTrue(successCount == 0 || isInitialized);
    }
}

