pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract so SetMinSum etc. can be called
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Initialized();
    }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 lockTime, uint256 warpTime) public {
        // Admissible domain: avoid zero-address funding, keep amounts reasonable
        address actor = address(0x100);
        vm.assume(depositAmt > 0 && depositAmt < 1e30);
        vm.assume(collectAmt > 0 && collectAmt < 1e30);
        vm.assume(lockTime < 1e18);
        vm.assume(warpTime > lockTime && warpTime < 1e18);
        // only well-funded deposits
        vm.assume(depositAmt >= collectAmt);

        // 1. Deposit via Put (the buggy version will ignore it)
        vm.prank(actor);
        vm.deal(actor, depositAmt);
        c.Put{value: depositAmt}(lockTime);

        // 2. Warp to after unlockTime
        vm.warp(warpTime);

        // 3. Record balance before Collect
        uint256 balBefore = c.Acc(actor);

        // 4. Collect
        vm.prank(actor);
        bool ok = true;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // 5. Record balance after Collect
        uint256 balAfter = c.Acc(actor);

        // Rule: if Collect succeeds, the recorded balance must decrease by exactly collectAmt.
        // The buggy Put recorded nothing, so balAfter will be zero instead of depositAmt - collectAmt.
        if (ok) {
            assertTrue(balAfter == balBefore - collectAmt);
        } else {
            // If Collect reverts, the balance must remain unchanged.
            assertTrue(balAfter == balBefore);
        }
    }
}

